"""Model-validated SYNTHETIC transport examples, never measured improvement."""
from datetime import UTC, datetime
from backend.app.models.feedback import RulePin, CaseReference, CaseView, FeedbackExamplePage, FeedbackPolicy, FeedbackPolicyCreate, FeedbackPolicyPage, GroundTruth, GroundTruthCreate, FeedbackEvaluation, FeedbackEvaluationCreate, FeedbackEvaluationStarted, FeedbackEvaluationPage, FeedbackPolicyActivate, ExecutionPin
from backend.app.models.rule import Rule
from backend.app.models.job import Job, JobKind

def feedback_examples():
    now = datetime(2026, 10, 21, tzinfo=UTC)
    rule = Rule(rule_id='SCENE-1', description='Annotation labels agree with the visible scene.', check_name='annotation_guideline', parameters={}, origin='reviewer', source_sentence=None, confirmation_state='confirmed')
    target = RulePin(rulebook_id='rulebook_feedback_demo', rulebook_version=1, rule=rule)
    training = CaseView(case_id='a' * 64, example_id='example_ZmluZGluZ19kZW1v.1', reference=CaseReference(audit_id='audit_training_demo', sample_id='training_001', sample_revision=1, rule_id=rule.rule_id), dataset_id='dataset_feedback_demo', target=target, expected='fail', image_sha256='b' * 64, annotation_sha256='c' * 64, reviewer_id='reviewer_demo', reviewed_at=now, reason='Human accepted the binary proposal.', finding_id='finding_demo', review_revision=1, correction_parent_revision=None, correction_reviewer_id=None, image_url='/api/v1/datasets/dataset_feedback_demo/samples/training_001/assets/image?revision=1')
    holdout = CaseView.model_validate(training.model_dump() | dict(case_id='d' * 64, example_id=None, reference=CaseReference(audit_id='audit_holdout_demo', sample_id='holdout_001', sample_revision=1, rule_id=rule.rule_id), image_sha256='e' * 64, reason='Human explicitly checked the pinned image and annotation against this rule.', finding_id=None, review_revision=0, image_url='/api/v1/datasets/dataset_feedback_demo/samples/holdout_001/assets/image?revision=1'))
    policy = FeedbackPolicy(policy_id='policy_demo', name='Reviewed scene examples', status='draft', snapshot_sha256='f' * 64, reviewer_id='reviewer_demo', created_at=now, examples=[training])
    truth = GroundTruth(ground_truth_id='truth_demo', snapshot_sha256='1' * 64, reviewer_id='reviewer_demo', created_at=now, cases=[holdout])
    execution = ExecutionPin(model='owner-installed-vision:demo', model_digest='sha256:' + '2' * 64)
    evaluation = FeedbackEvaluation(evaluation_id='evaluation_demo', job_id='job_feedback_demo', policy_id=policy.policy_id, policy_sha256=policy.snapshot_sha256, ground_truth_id=truth.ground_truth_id, truth_sha256=truth.snapshot_sha256, execution=execution, status='queued', created_at=now, metrics=None, results=[])
    job = Job.queued(job_id=evaluation.job_id, kind=JobKind.FEEDBACK_EVALUATION, total=1, now=now)
    responses = {'listFeedbackExamples': FeedbackExamplePage(items=[training], limit=20, offset=0, total=1, next_offset=None), 'createFeedbackPolicy': policy, 'getFeedbackPolicy': policy, 'listFeedbackPolicies': FeedbackPolicyPage(items=[policy], limit=20, offset=0, total=1, next_offset=None), 'createGroundTruth': truth, 'getGroundTruth': truth, 'evaluateFeedbackPolicy': FeedbackEvaluationStarted(evaluation=evaluation, job=job), 'getFeedbackEvaluation': evaluation, 'listFeedbackEvaluations': FeedbackEvaluationPage(items=[evaluation], limit=20, offset=0, total=1, next_offset=None), 'activateFeedbackPolicy': FeedbackPolicy.model_validate(policy.model_dump() | dict(status='active', activated_by='reviewer_demo', evaluation_id=evaluation.evaluation_id))}
    requests = {'createFeedbackPolicy': FeedbackPolicyCreate(name=policy.name, reviewer_id='reviewer_demo', example_ids=[training.example_id]), 'createGroundTruth': GroundTruthCreate.model_validate(dict(reviewer_id='reviewer_demo', cases=[holdout.reference.model_dump() | dict(expected=holdout.expected, reason=holdout.reason)])), 'evaluateFeedbackPolicy': FeedbackEvaluationCreate(policy_id=policy.policy_id, ground_truth_id=truth.ground_truth_id, reviewer_id='reviewer_demo'), 'activateFeedbackPolicy': FeedbackPolicyActivate(evaluation_id=evaluation.evaluation_id, reviewer_id='reviewer_demo')}
    return {'responses': {key: value.model_dump(mode='json') for key, value in responses.items()}, 'requests': {key: value.model_dump(mode='json') for key, value in requests.items()}}
